E=json.loads((Path(__file__).resolve().parents[1]/'shared/workshop-edition.json').read_text(encoding='utf-8'))

def jobs(n,m):
 bundles={2:['R/W/P','B/T/C'],3:['R/P','B/W','T/C'],4:['R/P','B','T/C','W'],5:['R/P','B','T','W','C'],6:['R','B','T','W','C','P']}[n]
 return [bundles[(i-(m-1))%n] for i in range(n)]

